\begin{tikzpicture}[x=18mm,y=10mm,every node/.style={font=\fontsize{10}{12}\selectfont}]
\path[use as bounding box] (-1.6,-2.9) rectangle (2.5,5.9);
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{polynomialBlue}{HTML}{268CFF}
\draw[black,line width=0.5pt,->] (-1.35,0)--(2.15,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-2.6)--(0,3.35) node[above] {$y$};
\draw[polynomialBlue,line width=0.8pt,<->,domain=-1.05:1.85,samples=140] plot (\x,{\x*\x*(\x-1)});
\fill[black] (0,0) circle[radius=1.6pt];
\fill[black] (1,0) circle[radius=1.6pt];
\node[below left] at (0,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$0$\special{dvisvgm:raw </g>}};
\node[below] at (1,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$1$\special{dvisvgm:raw </g>}};
\node[polynomialBlue,anchor=south] at (0.4,4.8) {$y=x^2(x-1)$};
\end{tikzpicture}

