\begin{tikzpicture}[x=9mm,y=9mm,every node/.style={font=\fontsize{10}{12}\selectfont}]
\path[use as bounding box] (-4.1,-4) rectangle (4.3,4.5);
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{reciprocalBlue}{HTML}{268CFF}
\definecolor{comparisonRed}{HTML}{EF6068}
\draw[black,line width=0.5pt,->] (-3.8,0)--(4,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-3.6)--(0,3.7) node[above] {$y$};
\draw[comparisonRed,line width=0.8pt,<->] (-3.5,0)--(3.5,0);
\draw[reciprocalBlue,line width=0.8pt,<->,domain=0.32:3.5,samples=100] plot (\x,{1/\x});
\draw[reciprocalBlue,line width=0.8pt,<->,domain=-3.5:-0.32,samples=100] plot (\x,{1/\x});
\node[reciprocalBlue,anchor=west] at (0.8,2.5) {$y=\frac{1}{x}$};
\node[comparisonRed,anchor=south] at (2.45,-1.3) {$y=0$};
\end{tikzpicture}
